/**
 * The smoke test's write safety and its bundle (prompt 51): a run writes only
 * to this machine unless told otherwise, and `smoke/` runs from a folder of its
 * own with nothing installed.
 *
 * Run with `npm run test:scripts`.
 */

const assert = require('node:assert/strict');
const { spawn } = require('node:child_process');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const { after, describe, it } = require('node:test');

const { NODE_ENGINE, bundleFiles, writeBundle } = require('../generate-smoke-bundle');
const { mayWriteTo, parseArgs } = require('../smoke-api');
const {
  LIVE_SEED,
  cleanupTempFiles,
  silenceRequestLog,
  withServer,
} = require('../../mock-server/__tests__/helpers');

silenceRequestLog();

const folders = [];
after(() => {
  cleanupTempFiles();
  for (const folder of folders) fs.rmSync(folder, { recursive: true, force: true });
});

/** Runs a script with the Node running the tests; resolves with its exit code and output. */
function run(cwd, args) {
  return new Promise((resolve) => {
    const child = spawn(process.execPath, args, { cwd, env: { ...process.env, NODE_PATH: '' } });
    let output = '';
    child.stdout.on('data', (chunk) => {
      output += chunk;
    });
    child.stderr.on('data', (chunk) => {
      output += chunk;
    });
    child.on('close', (code) => resolve({ code, output }));
  });
}

describe('write safety', () => {
  const flags = (argv) => parseArgs(argv);

  it('writes to this machine unasked, and to nothing else', () => {
    for (const url of [
      'http://localhost:4000/api',
      'http://127.0.0.1:4000/api',
      'http://127.4.5.6/api',
      'http://[::1]:4000/api',
    ]) {
      assert.equal(mayWriteTo(url, flags([])), true, url);
    }
    for (const url of [
      'https://www.squaresnacres.com/api',
      'https://staging.example/api',
      'http://localhost.example/api',
      'http://10.0.0.4/api',
      'not a url',
    ]) {
      assert.equal(mayWriteTo(url, flags([])), false, url);
    }
  });

  it('writes to a remote host when told to, and nowhere when told not to', () => {
    assert.equal(mayWriteTo('https://staging.example/api', flags(['--allow-writes'])), true);
    assert.equal(mayWriteTo('https://staging.example/api', flags(['--allowWrites=true'])), true);
    assert.equal(mayWriteTo('http://localhost:4000/api', flags(['--read-only'])), false);
    assert.equal(
      mayWriteTo('https://staging.example/api', flags(['--allow-writes', '--read-only'])),
      false
    );
  });

  it('takes the compared server’s own credentials', () => {
    const options = flags([
      '--compare=https://www.squaresnacres.com/api/',
      '--compareEmail=admin@squaresnacres.com',
      '--compare-password=Admin@123',
    ]);
    assert.equal(options.compare, 'https://www.squaresnacres.com/api');
    assert.equal(options.compareEmail, 'admin@squaresnacres.com');
    assert.equal(options.comparePassword, 'Admin@123');
  });
});

describe('the smoke bundle', () => {
  it('needs nothing installed and only Node 20', () => {
    const files = bundleFiles();
    const manifest = JSON.parse(files.get('package.json'));

    assert.equal(manifest.engines.node, NODE_ENGINE);
    assert.equal(manifest.dependencies, undefined);
    assert.equal(manifest.devDependencies, undefined);
    assert.ok(files.has('README.md') && files.has('smoke-api.js'));
    assert.ok(files.has('lib/src/services/endpoints.js'));
    assert.ok(files.has('lib/scripts/lib/guidelines/fixtures.js'));

    // The entry point reaches the copies, never the repository.
    const entry = files.get('smoke-api.js');
    assert.ok(entry.startsWith('#!/usr/bin/env node\n// Generated by'));
    for (const [, specifier] of entry.matchAll(/require\('([^']+)'\)/g)) {
      assert.ok(specifier.startsWith('./lib/'), specifier);
      assert.ok(files.has(specifier.slice(2)), specifier);
    }
  });

  it('runs from a folder outside the repository against the mock', async () => {
    const folder = fs.mkdtempSync(path.join(os.tmpdir(), 'sna-smoke-bundle-'));
    folders.push(folder);
    writeBundle(folder);

    // The seed the walk is written against: `db.json`, as `npm run mock` serves it.
    await withServer({ seed: LIVE_SEED }, async ({ origin }) => {
      const full = await run(folder, ['smoke-api.js', `--baseUrl=${origin}/api`]);
      assert.equal(full.code, 0, full.output.slice(-2000));
      assert.match(full.output, /\n(\d+)\/\1 checks passed, 0 failed\./);

      const reads = await run(folder, ['smoke-api.js', `--baseUrl=${origin}/api`, '--read-only']);
      assert.equal(reads.code, 0, reads.output.slice(-2000));
      assert.match(reads.output, /Reads only: --read-only was passed/);
      assert.doesNotMatch(reads.output, /Refused on the way out/);
    });
  });
});
